cd /tmp; cat > migrate.py <<'EOF'
import redis, sys
SRC=dict(host='127.0.0.1',port=6379); DST=dict(host='127.0.0.1',port=6380)
def raw(c): return c
stats={}
for db in range(16):
    s=redis.Redis(db=db,**SRC); d=redis.Redis(db=db,**DST)
    if s.dbsize()==0: continue
    n=0
    for k in s.scan_iter(count=1000):
        t=s.type(k).decode()
        p=d.pipeline(transaction=True)
        if t=='string':
            v=s.get(k)
            if v is None: continue
            p.set(k,v)
        elif t=='list':
            v=s.lrange(k,0,-1); p.rpush(k,*v)
        elif t=='set':
            v=list(s.smembers(k)); p.sadd(k,*v)
        elif t=='zset':
            v=s.zrange(k,0,-1,withscores=True,score_cast_func=lambda x:x)
            args=[]
            for m,sc in v: args+= [sc,m]
            p.execute_command('ZADD',k,*args)
        elif t=='hash':
            v=s.hgetall(k); fl=list(v.keys())
            args=[]
            for f in fl: args+=[f,v[f]]
            p.execute_command('HSET',k,*args)
            ets=s.execute_command('HPEXPIRETIME',k,'FIELDS',len(fl),*fl)
            for f,e in zip(fl,ets):
                if e>0: p.execute_command('HPEXPIREAT',k,e,'FIELDS',1,f)
                elif e==-2: raise Exception(('field vanished',k,f))
        elif t=='stream':
            info=s.execute_command('XINFO','STREAM',k,'FULL','COUNT',0)
            for eid,fields in s.xrange(k,'-','+'):
                p.execute_command('XADD',k,eid,*[x for kv in fields.items() for x in kv]) if False else None
            # use raw XRANGE to preserve duplicate field names / order
            ents=s.execute_command('XRANGE',k,'-','+')
            for eid,fields in ents:
                if isinstance(fields,dict): raise Exception('dict fields')
                p.execute_command('XADD',k,eid,*fields)
            if not ents:
                p.execute_command('XADD',k,'0-1','x','y'); p.execute_command('XDEL',k,'0-1')
            p.execute_command('XSETID',k,info[b'last-generated-id'],'ENTRIESADDED',info[b'entries-added'],'MAXDELETEDID',info[b'max-deleted-entry-id'])
            for g in info[b'groups']:
                a=['XGROUP','CREATE',k,g[b'name'],g[b'last-delivered-id']]
                if g[b'entries-read'] is not None: a+=['ENTRIESREAD',g[b'entries-read']]
                p.execute_command(*a)
                for c in g[b'consumers']:
                    p.execute_command('XGROUP','CREATECONSUMER',k,g[b'name'],c[b'name'])
                    for eid,dtime,cnt in c[b'pending']:
                        p.execute_command('XCLAIM',k,g[b'name'],c[b'name'],0,eid,'TIME',dtime,'RETRYCOUNT',cnt,'FORCE','JUSTID')
        else:
            raise Exception(('unsupported type',t,k))
        e=s.execute_command('PEXPIRETIME',k)
        if e>0: p.execute_command('PEXPIREAT',k,e)
        elif e==-2: p.reset(); continue
        p.execute()
        n+=1
    stats[db]=n
print(stats)
EOF
