cd /tmp; cat > verify.py <<'EOF'
import redis
def raw(c,*a):
    conn=c.connection_pool.get_connection()
    try:
        conn.send_command(*a); return conn.read_response()
    finally: c.connection_pool.release(conn)
bad=0; checked=0
def dump(c,k):
    t=c.type(k).decode()
    if t=='string': v=c.get(k)
    elif t=='list': v=c.lrange(k,0,-1)
    elif t=='set': v=sorted(c.smembers(k))
    elif t=='zset': v=c.zrange(k,0,-1,withscores=True,score_cast_func=lambda x:float(x))
    elif t=='hash':
        h=c.hgetall(k); fl=sorted(h)
        v=(sorted(h.items()), c.execute_command('HPEXPIRETIME',k,'FIELDS',len(fl),*fl))
    elif t=='stream':
        i=c.execute_command('XINFO','STREAM',k,'FULL','COUNT',0)
        gs=[]
        for g in i[b'groups']:
            gs.append((g[b'name'],g[b'last-delivered-id'],g[b'entries-read'],g[b'lag'],g[b'pel-count'],g[b'pending'],
              [(x[b'name'],x[b'pel-count'],x[b'pending']) for x in g[b'consumers']]))
        v=(raw(c,'XRANGE',k,'-','+'),i[b'length'],i[b'last-generated-id'],i[b'max-deleted-entry-id'],i[b'entries-added'],i[b'recorded-first-entry-id'],gs)
    return t,v,c.execute_command('PEXPIRETIME',k)
for db in range(16):
    s=redis.Redis(port=6379,db=db); d=redis.Redis(port=6380,db=db)
    sk=set(s.scan_iter(count=1000)); dk=set(d.scan_iter(count=1000))
    if sk!=dk: print('db',db,'keyset diff',len(sk-dk),len(dk-sk)); bad+=1
    for k in sk:
        checked+=1
        a=dump(s,k); b=dump(d,k)
        if a!=b: bad+=1; print('DIFF',db,k,a,b) if bad<10 else None
print('checked',checked,'bad',bad)
EOF
